    id: "R4B-001", lv: 3, tp: "vocab", theme: "Học tập và nỗ lực",
    cells: ["học", "hỏi", "lời", "chăm", "sách", "vở", "nhớ", "chỉ", "trì", "viết", "thành", "thi", "kiên", "đọc", "công", "rèn"],
    words: ["học hỏi", "chăm chỉ", "kiên trì", "thành công", "sách vở"],
